import fs from 'fs';
import path from 'path';
import { PDFDocument, PDFName } from 'pdf-lib';
import { mergeTaggedPdfs } from '../pdfMerge';
import { elementIds, readPdfStructure } from './helpers/pdfStructure';

// Chrome-printed fixtures, regenerated by fixtures/tagged-pdf-parts/generate.ts: a 5-page
// committee report printed whole, and as three slices (2 + 2 + 1 pages) in fresh browsers, in
// the legacy layout and (files prefixed `roster-`) as a roster with every column.
const dir = path.join(__dirname, 'fixtures/tagged-pdf-parts');
const read = (file: string) => new Uint8Array(fs.readFileSync(path.join(dir, file)));
const whole = read('whole.pdf');
const parts = ['part-0.pdf', 'part-1.pdf', 'part-2.pdf'].map(read);

describe('mergeTaggedPdfs', () => {
  it('the fixtures are what the merge has to handle: tagged parts that reuse element IDs', async () => {
    const [a, b] = await Promise.all(parts.slice(0, 2).map(elementIds));
    expect(a.length).toBeGreaterThan(0);
    expect(a.filter((id) => b.includes(id)).length).toBeGreaterThan(0);
    for (const part of parts) expect((await readPdfStructure(part)).errors).toEqual([]);
  });

  it.each([
    ['legacy', ''],
    ['roster, every column', 'roster-'],
  ])('%s: writes the structure tree Chrome writes when it prints the report in one piece', async (_mode, prefix) => {
    const expected = await readPdfStructure(read(`${prefix}whole.pdf`));
    const merged = await readPdfStructure(await mergeTaggedPdfs([0, 1, 2].map((i) => read(`${prefix}part-${i}.pdf`))));

    expect(expected.errors).toEqual([]);
    expect(merged.errors).toEqual([]);
    expect(merged.pages).toBe(5);
    expect(merged.catalog).toEqual(expected.catalog);
    expect(merged.catalog.MarkInfo).toContain('/Marked true');
    // Every table cell's /Headers resolve, to the header cells of its own table.
    expect(merged.headerRefs).toBe(expected.headerRefs);
    expect(merged.headerRefs).toBeGreaterThan(0);
    expect(merged.markedContent).toBe(expected.markedContent);
    expect(merged.nodes).toEqual(expected.nodes);
  });

  it('keeps every element ID unique', async () => {
    const ids = await elementIds(await mergeTaggedPdfs(parts));
    expect(new Set(ids).size).toBe(ids.length);
    expect(ids).toEqual([...ids].sort());
  });

  it('keeps the first part’s document info (title)', async () => {
    const merged = await PDFDocument.load(await mergeTaggedPdfs(parts), { updateMetadata: false });
    expect(merged.getTitle()).toBe('Committee Report');
  });

  it('is a no-op on the structure of a single part', async () => {
    const one = await readPdfStructure(await mergeTaggedPdfs([whole]));
    expect(one.errors).toEqual([]);
    expect(one.nodes).toEqual((await readPdfStructure(whole)).nodes);
  });

  it('refuses parts without a structure tree instead of writing an untagged merge', async () => {
    const untagged = await PDFDocument.create();
    untagged.addPage();
    await expect(mergeTaggedPdfs([parts[0], await untagged.save()])).rejects.toThrow(/slice 1 has no structure tree/);
  });

  it('refuses a structure root that is not one Document element', async () => {
    const doc = await PDFDocument.load(parts[1], { updateMetadata: false });
    const root = doc.context.lookup(doc.catalog.get(PDFName.of('StructTreeRoot'))) as unknown as {
      set: (k: PDFName, v: unknown) => void;
    };
    root.set(PDFName.of('K'), doc.context.obj([]));
    await expect(mergeTaggedPdfs([parts[0], await doc.save()])).rejects.toThrow(/not a single Document element/);
  });

  it('refuses no input', async () => {
    await expect(mergeTaggedPdfs([])).rejects.toThrow(/no PDFs/);
  });
});
